#!/usr/bin/env node
// Ivanexo website: elegant animated home page, About/Vision/Mission, icons instead of emoji,
// new fonts, store buttons. Run from the website root, after apply-website-home.js.
const fs = require("fs");
const path = require("path");
const OPS = JSON.parse(Buffer.from("", "base64").toString("utf8"));
const L = (s) => Buffer.from(s, "utf8").toString("latin1");
const root = process.cwd();
const dir = path.join(root, "src", "components");
const fail = (m) => { console.error("FAIL: " + m + "\nNothing was changed."); process.exit(1); };
if (!fs.existsSync(dir)) fail("src/components not found. Run this inside C:\\Users\\25078\\ivanexo-website");

const out = {};
const load = (p) => {
  if (out[p]) return out[p];
  if (!fs.existsSync(p)) fail("missing file " + path.relative(root, p));
  const raw = fs.readFileSync(p, "latin1");
  const eol = raw.includes("\r\n") ? "\r\n" : "\n";
  return (out[p] = { text: raw.replace(/\r\n/g, "\n"), eol, orig: raw });
};
const count = (t, s) => (s ? t.split(s).length - 1 : 0);

const hero = load(path.join(dir, "Hero.tsx")).text;
if (hero.includes("ixReveal")) { console.log("Already applied."); process.exit(0); }
if (!hero.includes("Powering business")) fail("Run apply-website-home.js first (it has not been applied).");

// the icon names used must exist in the installed lucide-react
try {
  const lu = require(path.join(root, "node_modules", "lucide-react"));
  const need = ["Smartphone","Layers","LifeBuoy","Lightbulb","Eye","Target","ShieldCheck","MessageCircle","Lock","Globe","Mail","Phone","MapPin","Package","Banknote","TrendingUp","Users","Cookie","ArrowUp"];
  const miss = need.filter((n) => !lu[n]);
  if (miss.length) fail("lucide-react is missing icons: " + miss.join(", ") + ". Run: npm install lucide-react@latest");
} catch (e) { if (String(e.message).startsWith("FAIL")) throw e; console.log("note: could not check lucide-react icons (" + e.code + ")"); }

for (const [f, r] of Object.entries(OPS.rewrite)) {
  const o = load(path.join(dir, f));
  if (!o.text.includes(L(r.anchor))) fail(f + ": expected content not found (file differs from what I checked)");
  o.text = L(r.content).replace(/\r\n/g, "\n");
}
for (const [f, list] of Object.entries(OPS.edit)) {
  const o = load(path.join(dir, f));
  list.forEach((e, i) => {
    if (e.prepend !== undefined) { o.text = L(e.prepend) + o.text; return; }
    const find = L(e.find);
    if (count(o.text, find) !== 1) fail(f + " edit #" + (i + 1) + ": found " + count(o.text, find) + " matches, expected 1");
    o.text = o.text.split(find).join(L(e.repl));
  });
}
// fonts: Clash Display -> Jost, Satoshi -> Manrope on every public-site component
for (const f of fs.readdirSync(dir).filter((x) => x.endsWith(".tsx"))) {
  const o = load(path.join(dir, f));
  o.text = o.text.split('"Clash Display"').join('"Jost"').split('"Satoshi"').join('"Manrope"');
}
// index.html: title, description, Google Fonts
const TITLE = "Ivanexo | Software, apps and IT support in Kigali";
const DESC = "Ivanexo builds websites, mobile apps and business software, and provides IT support for businesses in Rwanda. Makers of Trackly.";
const FONTS = '<link rel="preconnect" href="https://fonts.googleapis.com" />\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />\n  <link href="https://fonts.googleapis.com/css2?family=Jost:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet" />\n  <style>html body, button, input, textarea { font-family: "Manrope", sans-serif; }</style>';
let htmlDone = false;
for (const n of [path.join("public", "index.html"), "index.html"]) {
  const p = path.join(root, n);
  if (!fs.existsSync(p)) continue;
  const o = load(p);
  if (/<title>[^<]*<\/title>/.test(o.text)) o.text = o.text.replace(/<title>[^<]*<\/title>/, "<title>" + TITLE + "</title>");
  const meta = '<meta name="description" content="' + DESC + '" />';
  if (/<meta\s+name="description"[^>]*>/.test(o.text)) o.text = o.text.replace(/<meta\s+name="description"[^>]*>/, meta);
  else if (o.text.includes("</head>")) o.text = o.text.replace("</head>", "  " + meta + "\n  </head>");
  if (!o.text.includes("family=Jost") && o.text.includes("</head>")) { o.text = o.text.replace("</head>", "  " + FONTS + "\n  </head>"); htmlDone = true; }
}
if (!htmlDone) console.log("note: fonts link not added (already present or no index.html found)");

let changed = 0;
for (const [p, o] of Object.entries(out)) {
  const data = o.eol === "\r\n" ? o.text.replace(/\n/g, "\r\n") : o.text;
  if (data !== o.orig) { fs.writeFileSync(p, data, "latin1"); changed++; console.log("updated  " + path.relative(root, p)); }
}
console.log("\nDone. " + changed + " files updated. Now run:  npm run build");
